INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002bd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the digital public sphere at B2","Use Digitale Öffentlichkeit vocabulary","Talk about social media, filter bubbles, and online civic discourse in Germany"],"explanation":{"intro":"Digital public sphere vocabulary covers social media platforms, filter bubbles, and the transformation of democratic discourse at B2.","culturalNote":"Digitale Öffentlichkeit: Habermas''s Öffentlichkeit (public sphere — rational discourse → legitimacy) now fragmented by social media. Key: Filter-Blase (filter bubble — Eli Pariser 2011), Echokammer (echo chamber — homophily), Algorithmic curation. Hassrede (hate speech) — NetzDG (Netzwerkdurchsetzungsgesetz — Germany''s Network Enforcement Act 2017 — controversial: platforms must delete illegal content within 24-48h or face €50m fine). Diskursverengung (narrowing of discourse). Key institutions: Bundeszentrale für politische Bildung (Federal Agency for Civic Education — bpb), ARD Mediathek vs. Netflix. Desinformation (disinformation). Key debates: Algorithmic amplification of extreme content, Plattformregulierung (platform regulation — EU DSA 2022)."},"examples":[{"german":"Die digitale Öffentlichkeit hat die Habermassche Idee des rationalen Diskurses unter Druck gesetzt: Während klassische Medien eine gemeinsame Informationsbasis ermöglichten, erzeugen algorithmische Kurationssysteme personalisierte Informationsumgebungen, die strukturell auf Bestätigung statt Konfrontation ausgelegt sind.","english":"The digital public sphere has put Habermas''s idea of rational discourse under pressure: while classical media enabled a shared information base, algorithmic curation systems generate personalised information environments that are structurally designed for confirmation rather than confrontation."},{"german":"Hassrede und Desinformation stellen demokratische Öffentlichkeiten vor ein Dilemma: Zu wenig Regulierung toleriert Inhalte, die demokratischen Diskurs vergiften; zu viel Regulierung riskiert Zensur und staatlichen Missbrauch — eine Spannung, die sich nicht durch einfache Verbote, sondern nur durch transparente, rechtstaatlich gerahmte Verfahren lösen lässt.","english":"Hate speech and disinformation confront democratic public spheres with a dilemma: too little regulation tolerates content that poisons democratic discourse; too much regulation risks censorship and state abuse — a tension that can be resolved not through simple prohibitions, but only through transparent, rule-of-law-framed procedures."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s NetzDG, filter bubbles, and digital public sphere challenges at B2."}}',
'{"items":[{"word":"die Kuration","translation":"curation","pronunciation":"dee koo-rah-TSYOHN","example":"Algorithmische Kuration."},{"word":"ausgelegt auf","translation":"designed for","pronunciation":"OWS-geh-laykt owf","example":"Auf Bestätigung ausgelegt."},{"word":"vergiften","translation":"to poison","pronunciation":"fer-GIF-ten","example":"Diskurs vergiften."},{"word":"riskieren","translation":"to risk","pronunciation":"ris-KEE-ren","example":"Zensur riskieren."},{"word":"gerahmt","translation":"framed","pronunciation":"geh-RAHMT","example":"Rechtstaatlich gerahmt."},{"word":"das Verfahren","translation":"procedure","pronunciation":"dahs fer-FAH-ren","example":"Transparentes Verfahren."}]}',
'{"title":"Auf X ausgelegt sein — to be designed for X (built-in orientation)","pattern":"etwas ist auf X ausgelegt = something is designed/oriented towards X (auf...ausgelegt sein = to be designed for — ausgelegt + auf + accusative; marks the built-in orientation or purpose of a system, institution, or design)","explanation":"Auf X ausgelegt sein = to be designed for X, to be oriented towards X (auf + accusative + ausgelegt — past participle as adjective). Algorithmic systems are structurally designed for confirmation: auf Bestätigung ausgelegt. The phrase marks structural bias or intentional design, not just accidental tendency. Compare: konzipiert für (designed/conceived for — more deliberately architectural), abgestimmt auf (tuned/adjusted for — more calibration), optimiert für (optimised for — more quantitative), darauf abzielen X zu tun (aim at doing X — more goal-directedness).","examples":[{"sentence":"Das System ist auf maximalen Konsum ausgelegt.","translation":"The system is designed for maximum consumption."},{"sentence":"Die App ist auf junge Nutzer ausgelegt.","translation":"The app is designed for young users."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vergiften'' means?","options":["to poison","to corrupt","to contaminate","to taint"],"correctAnswer":"to poison"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The digital public sphere has put Habermas''s idea of rational discourse under pressure: while classical media enabled a shared information base, algorithmic curation systems generate personalised information environments that are structurally designed for confirmation rather than confrontation.","options":["Die digitale Öffentlichkeit hat die Habermassche Idee des rationalen Diskurses unter Druck gesetzt: Während klassische Medien eine gemeinsame Informationsbasis ermöglichten, erzeugen algorithmische Kurationssysteme personalisierte Informationsumgebungen, die strukturell auf Bestätigung statt Konfrontation ausgelegt sind.","Filter-Blasen verhindern echten politischen Diskurs.","Algorithmen erzeugen Echokammern, die das Denken einengen.","Soziale Medien haben die öffentliche Debatte qualitativ verschlechtert."],"correctAnswer":"Die digitale Öffentlichkeit hat die Habermassche Idee des rationalen Diskurses unter Druck gesetzt: Während klassische Medien eine gemeinsame Informationsbasis ermöglichten, erzeugen algorithmische Kurationssysteme personalisierte Informationsumgebungen, die strukturell auf Bestätigung statt Konfrontation ausgelegt sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System ist auf maximalen Konsum ___.","options":["ausgelegt","eingerichtet","abgestimmt","konzipiert"],"correctAnswer":"ausgelegt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The app is designed for young users","wordBankItems":["Die","App","ist","auf","junge","Nutzer","ausgelegt","."],"correctAnswer":"Die App ist auf junge Nutzer ausgelegt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Verfahren'' means?","options":["procedure","process","method","approach"],"correctAnswer":"procedure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002be',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss algorithms and power at B2","Use Algorithmen und Macht vocabulary","Talk about algorithmic decision-making, discrimination, and accountability"],"explanation":{"intro":"Algorithms and power vocabulary covers algorithmic decision-making, discrimination, and the politics of automated systems at B2.","culturalNote":"Algorithmen und Macht: Key concept: Algorithmic governance — algorithms make decisions with social consequences (creditworthiness, job applications, bail, insurance). Discriminatory algorithms: training data bias → algorithmic bias (Cathy O''Neil ''Weapons of Math Destruction'' 2016). Germany/EU: DSGVO (GDPR — Art. 22: right not to be subject to solely automated decisions with significant effects — Auskunft über automatisierte Entscheidung). EU AI Act (2024 — risk-based classification of AI systems). Algocratie (algocracy — rule by algorithm). Explainability (Erklärbarkeit — XAI — Explainable AI). Opacity: Black-box algorithms. Accountability problem: if algorithm fails, who is responsible? Key phrase: Algorithmen sind keine neutralen Werkzeuge — ''Algorithms are not neutral tools.''"},"examples":[{"german":"Algorithmen sind materialisierte Werturteile: Sie wurden von Menschen mit bestimmten Zielen, Daten und Entscheidungen gebaut, und ihre Outputs reproduzieren oder verstärken systematisch Ungleichheiten, die in ihren Trainingsdaten eingeschrieben sind — eine Tatsache, die durch die Oberfläche technischer Neutralität häufig verdeckt wird.","english":"Algorithms are materialised value judgements: they were built by humans with specific goals, data, and decisions, and their outputs systematically reproduce or amplify inequalities inscribed in their training data — a fact that is frequently obscured by the surface of technical neutrality."},{"german":"Die gesellschaftliche Herausforderung automatisierter Entscheidungssysteme ist nicht die KI selbst, sondern der Rechenschaftsmangel: Wenn ein Algorithmus über Kreditwürdigkeit, Jobbewerbungen oder Risikoeinschätzungen entscheidet, muss klar sein, wer für Fehlentscheidungen haftet und wie Betroffene Einspruch erheben können.","english":"The societal challenge of automated decision-making systems is not AI itself, but the accountability gap: when an algorithm decides on creditworthiness, job applications, or risk assessments, it must be clear who is liable for wrong decisions and how affected parties can raise objections."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss algorithmic bias, GDPR Art. 22, and algorithmic accountability at B2."}}',
'{"items":[{"word":"materialisiert","translation":"materialised","pronunciation":"mah-teh-ree-ah-li-ZEERT","example":"Materialisierte Werturteile."},{"word":"eingeschrieben","translation":"inscribed","pronunciation":"YN-geh-shree-ben","example":"Eingeschrieben in Daten."},{"word":"verdecken","translation":"to obscure","pronunciation":"fer-DEK-en","example":"Durch Neutralität verdeckt."},{"word":"die Rechenschaft","translation":"accountability","pronunciation":"dee REKH-en-shaft","example":"Rechenschaftsmangel."},{"word":"haften","translation":"to be liable","pronunciation":"HAF-ten","example":"Für Fehler haften."},{"word":"der Einspruch","translation":"objection","pronunciation":"dayr YN-shprukhh","example":"Einspruch erheben."}]}',
'{"title":"In X eingeschrieben sein — to be inscribed in X (structural embedding)","pattern":"etwas ist in X eingeschrieben = something is inscribed in X (einschreiben = to inscribe — past participle: eingeschrieben; in + dative marks the substrate)","explanation":"In X eingeschrieben sein = to be inscribed in X, to be structurally embedded in X (eingeschrieben — past participle used as adjective; in + dative). Inequalities inscribed in training data: in den Trainingsdaten eingeschrieben. The phrase marks that something is structurally embedded, not externally added — it''s baked in. Usually used critically: norms, hierarchies, biases inscribed in structures, technologies, texts. Compare: verankert in (anchored in — more stable/positive), impliziert in (implied in — more logical), kodiert in (encoded in — more technical), eingebettet in (embedded in — more spatial).","examples":[{"sentence":"Sexismus ist in vielen gesellschaftlichen Strukturen eingeschrieben.","translation":"Sexism is inscribed in many social structures."},{"sentence":"Die Werte der Gründer sind in der Unternehmenskultur eingeschrieben.","translation":"The founders'' values are inscribed in the company culture."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Haften'' means?","options":["to be liable","to be responsible","to be accountable","to answer for"],"correctAnswer":"to be liable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Algorithms are materialised value judgements: they were built by humans with specific goals, data, and decisions, and their outputs systematically reproduce or amplify inequalities inscribed in their training data — a fact that is frequently obscured by the surface of technical neutrality.","options":["Algorithmen sind materialisierte Werturteile: Sie wurden von Menschen mit bestimmten Zielen, Daten und Entscheidungen gebaut, und ihre Outputs reproduzieren oder verstärken systematisch Ungleichheiten, die in ihren Trainingsdaten eingeschrieben sind — eine Tatsache, die durch die Oberfläche technischer Neutralität häufig verdeckt wird.","Algorithmen sind nicht neutral — sie spiegeln die Werte ihrer Entwickler wider.","Algorithmische Diskriminierung entsteht durch verzerrte Trainingsdaten.","Technische Neutralität ist oft eine Illusion."],"correctAnswer":"Algorithmen sind materialisierte Werturteile: Sie wurden von Menschen mit bestimmten Zielen, Daten und Entscheidungen gebaut, und ihre Outputs reproduzieren oder verstärken systematisch Ungleichheiten, die in ihren Trainingsdaten eingeschrieben sind — eine Tatsache, die durch die Oberfläche technischer Neutralität häufig verdeckt wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sexismus ist in vielen gesellschaftlichen Strukturen ___.","options":["eingeschrieben","verankert","eingebettet","kodiert"],"correctAnswer":"eingeschrieben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The founders values are inscribed in the company culture","wordBankItems":["Die","Werte","der","Gründer","sind","in","der","Unternehmenskultur","eingeschrieben","."],"correctAnswer":"Die Werte der Gründer sind in der Unternehmenskultur eingeschrieben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Einspruch'' means?","options":["objection","protest","appeal","challenge"],"correctAnswer":"objection"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002bf',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss data protection and surveillance at B2","Use Datenschutz und Überwachung vocabulary","Talk about GDPR, surveillance capitalism, and privacy rights in Germany"],"explanation":{"intro":"Data protection and surveillance vocabulary covers GDPR, surveillance capitalism, and Germany''s strong privacy culture at B2.","culturalNote":"Datenschutz und Überwachung: Germany: particularly strong privacy culture (Datenschutzkultur) — shaped by Stasi (East German secret police — Staatssicherheit — 180km of files — surveillance trauma). Key legal: Volkszählungsurteil (1983 Census Ruling — Bundesverfassungsgericht — right to informational self-determination — Recht auf informationelle Selbstbestimmung — landmark). DSGVO (GDPR — 2018 — gold standard globally). Bundesdatenschutzbehörde (Federal Data Protection Authority). Key concept: Shoshana Zuboff — Überwachungskapitalismus (surveillance capitalism — behavioral data as raw material — prediction products). NSA scandal (Snowden 2013 — Germans particularly outraged). Key phrase: ''Wer nichts zu verbergen hat...'' vs. ''Privatheit als Bedingung für Freiheit'' (privacy as condition for freedom)."},"examples":[{"german":"Das Recht auf informationelle Selbstbestimmung ist kein technisches Detail, sondern eine Grundvoraussetzung demokratischer Handlungsfähigkeit: Nur wer die Kontrolle über seine Daten behält, kann frei kommunizieren, sich politisch engagieren und die eigene Identität ohne staatliche oder kommerzielle Überwachung gestalten.","english":"The right to informational self-determination is not a technical detail, but a fundamental prerequisite for democratic agency: only those who retain control over their data can communicate freely, engage politically, and shape their own identity without state or commercial surveillance."},{"german":"Überwachungskapitalismus bezeichnet eine wirtschaftliche Logik, in der menschliches Verhalten zur Rohware für Prognoseprodukte wird: Die Vermessung von Aufmerksamkeit, Bewegung und sozialen Interaktionen speist Modelle, die zukünftiges Verhalten mit einer Genauigkeit vorhersagen, die herkömmliche Werbung weit übersteigt.","english":"Surveillance capitalism designates an economic logic in which human behaviour becomes raw material for prediction products: the measurement of attention, movement, and social interactions feeds models that predict future behaviour with an accuracy that far surpasses conventional advertising."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss GDPR, informational self-determination, and surveillance capitalism at B2."}}',
'{"items":[{"word":"die Selbstbestimmung","translation":"self-determination","pronunciation":"dee ZELPS-beh-shti-moong","example":"Informationelle Selbstbestimmung."},{"word":"sich engagieren","translation":"to engage","pronunciation":"zikh eng-ah-ZHEER-en","example":"Sich politisch engagieren."},{"word":"die Rohware","translation":"raw material","pronunciation":"dee ROH-vah-reh","example":"Rohware für Prognosen."},{"word":"speisen","translation":"to feed (into)","pronunciation":"SHPY-zen","example":"Modelle speisen."},{"word":"vorhersagen","translation":"to predict","pronunciation":"FOR-hayr-sah-gen","example":"Verhalten vorhersagen."},{"word":"herkömmlich","translation":"conventional","pronunciation":"hayr-KÖM-likh","example":"Herkömmliche Werbung."}]}',
'{"title":"Bezeichnet eine Logik, in der X zur Y wird — designates a logic in which X becomes Y","pattern":"etwas bezeichnet eine Logik/Ordnung, in der X zu Y wird = something designates a logic/order in which X becomes Y (bezeichnet = designates; eine Logik in der = a logic in which — relative clause; X zu Y wird = X becomes Y — werden)","explanation":"Bezeichnet eine Logik, in der X zu Y wird = designates a logic in which X becomes Y. Compound of: bezeichnen (to designate, define — more definitional than ''mean''), eine Logik (a logic — an underlying system of principles), in der ... wird (relative clause — in which X becomes Y). Used to define a concept by naming the transformation it performs on social entities: surveillance capitalism transforms human behaviour (X) into raw material (Y). Compare: eine Ordnung, in der (an order in which), ein System, in dem (a system in which), eine Dynamik, die X zu Y macht (a dynamic that turns X into Y).","examples":[{"sentence":"Neoliberalismus bezeichnet eine Logik, in der alles zur Ware wird.","translation":"Neoliberalism designates a logic in which everything becomes a commodity."},{"sentence":"Das bezeichnet eine Ordnung, in der Wissen zur Macht wird.","translation":"That designates an order in which knowledge becomes power."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vorhersagen'' means?","options":["to predict","to forecast","to foresee","to anticipate"],"correctAnswer":"to predict"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The right to informational self-determination is not a technical detail, but a fundamental prerequisite for democratic agency: only those who retain control over their data can communicate freely, engage politically, and shape their own identity without state or commercial surveillance.","options":["Das Recht auf informationelle Selbstbestimmung ist kein technisches Detail, sondern eine Grundvoraussetzung demokratischer Handlungsfähigkeit: Nur wer die Kontrolle über seine Daten behält, kann frei kommunizieren, sich politisch engagieren und die eigene Identität ohne staatliche oder kommerzielle Überwachung gestalten.","Datenschutz ist mehr als Technik — er ist Grundvoraussetzung für demokratisches Leben.","Informationelle Selbstbestimmung schützt politische Freiheit.","Ohne Kontrolle über die eigenen Daten gibt es keine echte Freiheit."],"correctAnswer":"Das Recht auf informationelle Selbstbestimmung ist kein technisches Detail, sondern eine Grundvoraussetzung demokratischer Handlungsfähigkeit: Nur wer die Kontrolle über seine Daten behält, kann frei kommunizieren, sich politisch engagieren und die eigene Identität ohne staatliche oder kommerzielle Überwachung gestalten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Neoliberalismus bezeichnet eine Logik, in der alles zur ___ wird.","options":["Ware","Ressource","Kapital","Gewinn"],"correctAnswer":"Ware"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That designates an order in which knowledge becomes power","wordBankItems":["Das","bezeichnet","eine","Ordnung",",","in","der","Wissen","zur","Macht","wird","."],"correctAnswer":"Das bezeichnet eine Ordnung , in der Wissen zur Macht wird ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Herkömmlich'' means?","options":["conventional","traditional","established","classical"],"correctAnswer":"conventional"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss AI and ethics at B2","Use Künstliche Intelligenz und Ethik vocabulary","Talk about Germany''s AI strategy, AI rights, and algorithmic ethics"],"explanation":{"intro":"AI and ethics vocabulary covers AI ethics frameworks, Germany''s AI strategy, and debates about autonomy and responsibility at B2.","culturalNote":"KI und Ethik: Germany: Datenethikkommission (Data Ethics Commission — 2019 report — risk-based AI regulation). EU AI Act (2024 — world''s first comprehensive AI law — risk categories: unacceptable/high/limited/minimal risk). Key ethical debates: Autonome Waffensysteme (autonomous weapons — killer robots), Algorithmic bias, Erklärbarkeit (explainability), Datensouveränität (data sovereignty). German Ethikrat (German Ethics Council — AI advisory). Key concepts: KI-Souveränität (AI sovereignty), Maschinenethik (machine ethics), Verantwortung beim Einsatz von KI (responsibility in AI deployment). Tech giants vs. national sovereignty. Key figure: Katharina Zweig (KI-Forscherin, Kaiserslautern). KI als Werkzeug vs. KI als Akteur debate."},"examples":[{"german":"Die Ethik der künstlichen Intelligenz ist keine nachgelagerte Kontrollaufgabe, sondern eine designintegrale Anforderung: Welche Ziele optimiert ein System, wessen Werte kodiert es, und wer ist verantwortlich, wenn automatisierte Entscheidungen Menschen schädigen — diese Fragen müssen im Entwicklungsprozess gestellt werden, nicht erst nach dem Schaden.","english":"The ethics of artificial intelligence is not a downstream control task, but a design-integral requirement: which goals a system optimises, whose values it encodes, and who is responsible when automated decisions harm people — these questions must be asked in the development process, not only after the damage."},{"german":"Das Risikobasierte Rahmenwerk der KI-Regulierung unterscheidet nach der Schwere möglicher Schäden: Systeme, die biologische oder soziale Grundrechte berühren — Gesichtserkennung im öffentlichen Raum, KI in Justiz und Strafverfolgung — unterliegen strengeren Anforderungen als solche mit niedrigem Schadensrisiko.","english":"The risk-based framework of AI regulation distinguishes according to the severity of possible harms: systems that touch on biological or social fundamental rights — facial recognition in public space, AI in justice and law enforcement — are subject to stricter requirements than those with low damage risk."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss AI ethics frameworks, EU AI Act, and design-integral ethics at B2."}}',
'{"items":[{"word":"nachgelagert","translation":"downstream","pronunciation":"NAKHH-geh-lah-gert","example":"Nachgelagerte Kontrolle."},{"word":"designintegriert","translation":"design-integral","pronunciation":"deh-SIGN-in-teh-griert","example":"Designintegrale Anforderung."},{"word":"schädigen","translation":"to harm","pronunciation":"SHÄ-di-gen","example":"Menschen schädigen."},{"word":"risikobasiert","translation":"risk-based","pronunciation":"ri-ZEE-ko-bah-zeert","example":"Risikobasiertes Rahmenwerk."},{"word":"berühren","translation":"to touch on","pronunciation":"beh-RÜ-ren","example":"Grundrechte berühren."},{"word":"unterliegen","translation":"to be subject to","pronunciation":"oon-ter-LEE-gen","example":"Strengen Anforderungen unterliegen."}]}',
'{"title":"Im Entwicklungsprozess X stellen, nicht erst nach Y — ask X in the development process, not only after Y","pattern":"etwas muss im Prozess X getan werden, nicht erst nach Y = something must be done in process X, not only after Y (nicht erst nach Y = not only/first after Y — marks temporal ordering, insisting on earlier action)","explanation":"Nicht erst nach Y = not only/first after Y (nicht erst = not only after — implying it should happen earlier). Im Entwicklungsprozess gestellt werden, nicht erst nach dem Schaden = asked in the development process, not only after the damage. The pattern insists on frontloading: the critical action must happen earlier in the sequence, not only as damage control. Compare: frühzeitig (early on — adverb), präventiv (preventively), im Vorfeld (in advance — before the event), von Anfang an (from the start — stronger), a priori vs. a posteriori (philosophical — before vs. after experience).","examples":[{"sentence":"Sicherheitsfragen müssen im Planungsprozess gestellt werden, nicht erst bei der Umsetzung.","translation":"Safety questions must be asked in the planning process, not only at implementation."},{"sentence":"Ethische Fragen müssen am Anfang bedacht werden, nicht erst am Ende.","translation":"Ethical questions must be considered at the start, not only at the end."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schädigen'' means?","options":["to harm","to damage","to injure","to hurt"],"correctAnswer":"to harm"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The ethics of artificial intelligence is not a downstream control task, but a design-integral requirement: which goals a system optimises, whose values it encodes, and who is responsible when automated decisions harm people — these questions must be asked in the development process, not only after the damage.","options":["Die Ethik der künstlichen Intelligenz ist keine nachgelagerte Kontrollaufgabe, sondern eine designintegrale Anforderung: Welche Ziele optimiert ein System, wessen Werte kodiert es, und wer ist verantwortlich, wenn automatisierte Entscheidungen Menschen schädigen — diese Fragen müssen im Entwicklungsprozess gestellt werden, nicht erst nach dem Schaden.","KI-Ethik muss von Anfang an in den Entwicklungsprozess integriert werden.","Fragen der Verantwortung für KI müssen vor dem Schaden gestellt werden.","Die Ethik der KI gehört in den Designprozess, nicht in die Schadensregulierung."],"correctAnswer":"Die Ethik der künstlichen Intelligenz ist keine nachgelagerte Kontrollaufgabe, sondern eine designintegrale Anforderung: Welche Ziele optimiert ein System, wessen Werte kodiert es, und wer ist verantwortlich, wenn automatisierte Entscheidungen Menschen schädigen — diese Fragen müssen im Entwicklungsprozess gestellt werden, nicht erst nach dem Schaden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sicherheitsfragen müssen im Planungsprozess gestellt werden, nicht erst bei der ___.","options":["Umsetzung","Durchführung","Realisierung","Anwendung"],"correctAnswer":"Umsetzung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Ethical questions must be considered at the start not only at the end","wordBankItems":["Ethische","Fragen","müssen","am","Anfang","bedacht","werden",",","nicht","erst","am","Ende","."],"correctAnswer":"Ethische Fragen müssen am Anfang bedacht werden , nicht erst am Ende ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterliegen'' means?","options":["to be subject to","to be governed by","to fall under","to comply with"],"correctAnswer":"to be subject to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss automation of work at B2","Use Automatisierung der Arbeit vocabulary","Talk about robotisation, future of work, and job market transformation in Germany"],"explanation":{"intro":"Automation of work vocabulary covers robotisation, structural unemployment, and the future of work in Germany at B2.","culturalNote":"Automatisierung der Arbeit: Germany: Industrie 4.0 (Industry 4.0 — smart factory — IoT — automation — coined in Germany 2011). Key: Frey & Osborne Oxford study (2013 — 47% of US jobs at risk). Germany: manufacturing (Automobil, Maschinenbau) — high automation risk, but also high skill base. IG Metall (metalworkers'' union — negotiating ''work 4.0''). Kurzarbeit (short-time work — government subsidy — Kurzarbeitergeld — prevents mass layoffs — widely used COVID-19). Qualifizierungsoffensive (upskilling initiative). Key debates: Will automation create more jobs than it destroys? (Optimists: new sectors; Pessimists: hollowing out of middle-income jobs). Key institution: IAB (Institut für Arbeitsmarkt- und Berufsforschung — labour market research). Universal Basic Income debate (Bedingungsloses Grundeinkommen)."},"examples":[{"german":"Automatisierung trifft nicht alle Berufsgruppen gleichermaßen: Routineaufgaben — sowohl manuelle als auch kognitive — sind am stärksten gefährdet, während kreative, soziale und analytisch nicht-standardisierbare Tätigkeiten vorerst schwerer zu automatisieren sind. Das führt zu einer Polarisierung des Arbeitsmarkts, bei der mittlere Qualifikationsebenen besonders unter Druck geraten.","english":"Automation does not affect all occupational groups equally: routine tasks — both manual and cognitive — are most at risk, while creative, social, and analytically non-standardisable activities are for the time being harder to automate. This leads to a polarisation of the labour market in which medium qualification levels come under particular pressure."},{"german":"Kurzarbeit ist ein deutsches Erfolgsmodell der Beschäftigungsstabilisierung: Indem es Arbeitgebern erlaubt, Arbeitszeiten zu reduzieren statt Stellen abzubauen, bewahrt es Humankapital, erhält soziale Stabilität und ermöglicht Unternehmen, nach einer Krisenphase schnell wieder auf erfahrene Belegschaften zurückzugreifen.","english":"Short-time work is a German success model of employment stabilisation: by allowing employers to reduce working hours rather than cutting jobs, it preserves human capital, maintains social stability, and enables companies to quickly fall back on experienced workforces after a crisis phase."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Industrie 4.0, labour polarisation, and Kurzarbeit at B2."}}',
'{"items":[{"word":"gleichermaßen","translation":"equally","pronunciation":"GLY-kheh-mah-sen","example":"Gleichermaßen betroffen."},{"word":"gefährdet","translation":"at risk","pronunciation":"geh-FÄR-det","example":"Am stärksten gefährdet."},{"word":"die Polarisierung","translation":"polarisation","pronunciation":"dee po-lah-ri-ZEE-roong","example":"Polarisierung des Markts."},{"word":"bewahren","translation":"to preserve","pronunciation":"beh-VAH-ren","example":"Humankapital bewahren."},{"word":"abbauen","translation":"to cut/reduce","pronunciation":"AB-bow-en","example":"Stellen abbauen."},{"word":"zurückgreifen auf","translation":"to fall back on","pronunciation":"tsu-RÜK-gry-fen owf","example":"Auf Belegschaft zurückgreifen."}]}',
'{"title":"Indem X, bewahrt/ermöglicht Y — by doing X, Y preserves/enables (gerundial means clause)","pattern":"indem X, bewahrt/erhält/ermöglicht Y + object = by doing X, Y preserves/maintains/enables (indem = by + gerund in German — subordinate clause with same subject or different subject; main clause states the result)","explanation":"Indem = by (doing something) — introduces a means clause. Indem es erlaubt, Arbeitszeiten zu reduzieren statt Stellen abzubauen, bewahrt es Humankapital = By allowing working hours to be reduced rather than cutting jobs, it preserves human capital. Note: indem always needs a finite verb in the subordinate clause (erlaubt), unlike English gerund (''by allowing''). The subject of the indem clause is often the same as the main clause. Compare: dadurch, dass (by the fact that — more formal/paraphrastic), durch + infinitive (by — + noun, not clause), wenn (if/when — conditional, not means).","examples":[{"sentence":"Indem sie sich weiterbildet, verbessert sie ihre Chancen.","translation":"By continuing her education, she improves her chances."},{"sentence":"Indem das Unternehmen kooperiert, gewinnt es neue Märkte.","translation":"By cooperating, the company gains new markets."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Abbauen'' means?","options":["to cut/reduce","to dismantle","to remove","to eliminate"],"correctAnswer":"to cut/reduce"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Short-time work is a German success model of employment stabilisation: by allowing employers to reduce working hours rather than cutting jobs, it preserves human capital, maintains social stability, and enables companies to quickly fall back on experienced workforces after a crisis phase.","options":["Kurzarbeit ist ein deutsches Erfolgsmodell der Beschäftigungsstabilisierung: Indem es Arbeitgebern erlaubt, Arbeitszeiten zu reduzieren statt Stellen abzubauen, bewahrt es Humankapital, erhält soziale Stabilität und ermöglicht Unternehmen, nach einer Krisenphase schnell wieder auf erfahrene Belegschaften zurückzugreifen.","Kurzarbeit hilft Deutschland, Massenentlassungen zu vermeiden.","Durch Kurzarbeit können Unternehmen Kosten sparen, ohne Mitarbeiter zu entlassen.","Kurzarbeitergeld sichert die Beschäftigung in wirtschaftlichen Krisen."],"correctAnswer":"Kurzarbeit ist ein deutsches Erfolgsmodell der Beschäftigungsstabilisierung: Indem es Arbeitgebern erlaubt, Arbeitszeiten zu reduzieren statt Stellen abzubauen, bewahrt es Humankapital, erhält soziale Stabilität und ermöglicht Unternehmen, nach einer Krisenphase schnell wieder auf erfahrene Belegschaften zurückzugreifen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Indem sie sich weiterbildet, ___ sie ihre Chancen.","options":["verbessert","erhöht","steigert","erweitert"],"correctAnswer":"verbessert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: By cooperating the company gains new markets","wordBankItems":["Indem","das","Unternehmen","kooperiert",",","gewinnt","es","neue","Märkte","."],"correctAnswer":"Indem das Unternehmen kooperiert , gewinnt es neue Märkte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bewahren'' means?","options":["to preserve","to protect","to maintain","to conserve"],"correctAnswer":"to preserve"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the platform economy at B2","Use Plattformökonomie vocabulary","Talk about platform capitalism, gig economy, and regulation in Germany"],"explanation":{"intro":"Platform economy vocabulary covers platform capitalism, gig work, and debates about regulation at B2.","culturalNote":"Plattformökonomie: Key concept: Plattformkapitalismus (platform capitalism — Nick Srnicek). Winner-takes-all dynamics (Netzwerkeffekte — network effects). Key platforms in Germany: Lieferando (food delivery — German DoorDash), Gorillas/Flink (grocery delivery), Uber (limited in Germany — taxi-rules), Airbnb (vs. Mietpreisbremse). Key legal debate: Gig-Arbeit (gig work) — are platform workers Arbeitnehmer (employees) or Selbstständige (self-employed)? Spain classified riders as employees (''Ley Rider'' 2021). EU Platform Work Directive (2024 — presumption of employment). Plattformbesteuerung (platform taxation). Key: Amazon dominance in Germany — Marktmacht (market power). EU competition law vs. Big Tech (Digital Markets Act 2022). Key term: Plattformneutralität (platform neutrality)."},"examples":[{"german":"Die Plattformökonomie erzeugt eine paradoxe Konstellation: Während sie unternehmerische Freiheit für Anbieter propagiert, konzentriert sie in der Praxis Marktmacht und Ressourcen bei einer kleinen Zahl von Infrastrukturbesitzern, deren Plattformen de facto zu privatisierten öffentlichen Räumen geworden sind, auf deren Regeln die Nutzer keinen demokratischen Einfluss haben.","english":"The platform economy produces a paradoxical constellation: while it propagates entrepreneurial freedom for providers, in practice it concentrates market power and resources among a small number of infrastructure owners, whose platforms have de facto become privatised public spaces on whose rules users have no democratic influence."},{"german":"Plattformarbeiter befinden sich in einer rechtlichen Grauzone: Als formal Selbstständige tragen sie unternehmerische Risiken ohne unternehmerische Kontrolle — sie können die Algorithmen, die ihre Auftragszuteilung, Preissetzung und Bewertung steuern, weder einsehen noch beeinflussen, was die klassische Kategorisierung von Arbeit und Kapital untergräbt.","english":"Platform workers find themselves in a legal grey zone: as formally self-employed, they bear entrepreneurial risks without entrepreneurial control — they can neither see nor influence the algorithms that control their job allocation, pricing, and evaluation, which undermines the classical categorisation of labour and capital."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss platform capitalism, gig work regulation, and network effects at B2."}}',
'{"items":[{"word":"propagieren","translation":"to propagate","pronunciation":"pro-pah-GHEE-ren","example":"Freiheit propagieren."},{"word":"die Grauzone","translation":"grey zone","pronunciation":"dee GROW-tso-neh","example":"Rechtliche Grauzone."},{"word":"einsehen","translation":"to see/inspect","pronunciation":"YN-zay-en","example":"Algorithmen einsehen."},{"word":"beeinflussen","translation":"to influence","pronunciation":"beh-YN-floo-sen","example":"Preise beeinflussen."},{"word":"die Auftragszuteilung","translation":"job allocation","pronunciation":"dee OWF-trahks-tsoo-ty-loong","example":"Algorithmische Auftragszuteilung."},{"word":"untergraben","translation":"to undermine","pronunciation":"oon-ter-GRAH-ben","example":"Kategorien untergraben."}]}',
'{"title":"Weder einsehen noch beeinflussen können — to be able to neither inspect nor influence","pattern":"etwas weder einsehen noch beeinflussen können = to be able to neither inspect nor influence something (weder...noch = neither...nor — correlative conjunction; with a modal: können or dürfen or müssen governs both verbs)","explanation":"Weder...noch = neither...nor (correlative conjunction). With a modal verb like können: sie können weder einsehen noch beeinflussen = they can neither see nor influence. Note: both verbs are infinitives after können; weder comes before the first, noch before the second. Grammar: weder X noch Y (neither X nor Y) — both X and Y must be syntactically parallel: both infinitives, or both noun phrases, or both adjective phrases. Compare: sowohl...als auch (both...and — additive positive), entweder...oder (either...or — disjunctive), nicht...und auch nicht (not...and also not — non-correlative alternative).","examples":[{"sentence":"Er konnte weder schlafen noch arbeiten.","translation":"He could neither sleep nor work."},{"sentence":"Sie konnten weder kommen noch absagen.","translation":"They could neither come nor cancel."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Untergraben'' means?","options":["to undermine","to subvert","to erode","to destabilise"],"correctAnswer":"to undermine"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Platform workers find themselves in a legal grey zone: as formally self-employed, they bear entrepreneurial risks without entrepreneurial control — they can neither see nor influence the algorithms that control their job allocation, pricing, and evaluation, which undermines the classical categorisation of labour and capital.","options":["Plattformarbeiter befinden sich in einer rechtlichen Grauzone: Als formal Selbstständige tragen sie unternehmerische Risiken ohne unternehmerische Kontrolle — sie können die Algorithmen, die ihre Auftragszuteilung, Preissetzung und Bewertung steuern, weder einsehen noch beeinflussen, was die klassische Kategorisierung von Arbeit und Kapital untergräbt.","Gig-Arbeiter sind formal selbstständig, aber faktisch wie Angestellte behandelt.","Plattformbeschäftigte haben keine Kontrolle über die Algorithmen, die sie steuern.","Die Klassifikation von Plattformarbeitern als selbstständig ist rechtlich fragwürdig."],"correctAnswer":"Plattformarbeiter befinden sich in einer rechtlichen Grauzone: Als formal Selbstständige tragen sie unternehmerische Risiken ohne unternehmerische Kontrolle — sie können die Algorithmen, die ihre Auftragszuteilung, Preissetzung und Bewertung steuern, weder einsehen noch beeinflussen, was die klassische Kategorisierung von Arbeit und Kapital untergräbt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er konnte weder schlafen noch ___.","options":["arbeiten","essen","sprechen","schreiben"],"correctAnswer":"arbeiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: They could neither come nor cancel","wordBankItems":["Sie","konnten","weder","kommen","noch","absagen","."],"correctAnswer":"Sie konnten weder kommen noch absagen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Propagieren'' means?","options":["to propagate","to promote","to advocate","to spread"],"correctAnswer":"to propagate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss freedom of information at B2","Use Informationsfreiheit vocabulary","Talk about press freedom, transparency laws, and information rights in Germany"],"explanation":{"intro":"Freedom of information vocabulary covers press freedom, Germany''s transparency laws, and the right to information at B2.","culturalNote":"Informationsfreiheit: Germany: Pressefreiheit (press freedom) guaranteed in GG Art. 5. Informationsfreiheitsgesetz (IFG — Freedom of Information Act — federal 2006 — right to access official documents). Transparenzgesetze (transparency laws — Hamburg has strongest). Key: RSF (Reporters Without Borders) press freedom index — Germany usually top 10 (2024: rank 10). Whistleblowing: Hinweisgeberschutzgesetz (Whistleblower Protection Act — 2023 — EU Directive). Julian Assange, Edward Snowden cases. Öffentlich-rechtlicher Rundfunk (public broadcasting — ARD, ZDF — financed by Rundfunkbeitrag — independent from state — key public service function). Key debate: Redaktionsgeheimnis (editorial secrecy), source protection (Quellenschutz). Press concentration (Medienkonzentration) — increasing in Germany."},"examples":[{"german":"Informationsfreiheit ist eine strukturelle Voraussetzung demokratischer Kontrolle: Nur wenn Bürgerinnen und Bürger Zugang zu Informationen über Regierungshandeln haben, können sie ihre Regierungen rechenschaftspflichtig machen und fundierte politische Entscheidungen treffen. Behörden, die Informationen zurückhalten, verschieben das Machtgefüge zugunsten der Verwaltung.","english":"Freedom of information is a structural prerequisite for democratic control: only when citizens have access to information about government action can they hold their governments to account and make informed political decisions. Authorities that withhold information shift the balance of power in favour of the administration."},{"german":"Whistleblowing befindet sich in einem Spannungsfeld zwischen Loyalitätspflicht und demokratischer Transparenzforderung: Wer interne Missstände öffentlich macht, riskiert berufliche und rechtliche Konsequenzen, dient aber einer öffentlichen Funktion — eine Spannung, die erst durch wirksamen rechtlichen Schutz für Hinweisgeber auflösbar wird.","english":"Whistleblowing finds itself in a tension between loyalty obligation and democratic transparency demand: those who make internal grievances public risk professional and legal consequences, but serve a public function — a tension that can only be resolved through effective legal protection for whistleblowers."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s freedom of information law, press freedom, and whistleblower protection at B2."}}',
'{"items":[{"word":"rechenschaftspflichtig","translation":"accountable","pronunciation":"REKH-en-shafts-pfl-ikh-tikh","example":"Regierung rechenschaftspflichtig machen."},{"word":"fundiert","translation":"informed/well-founded","pronunciation":"foon-DEERT","example":"Fundierte Entscheidung."},{"word":"zurückhalten","translation":"to withhold","pronunciation":"tsu-RÜK-hal-ten","example":"Informationen zurückhalten."},{"word":"das Machtgefüge","translation":"balance/structure of power","pronunciation":"dahs MAKHT-geh-fü-geh","example":"Machtgefüge verschieben."},{"word":"der Missstand","translation":"grievance/abuse","pronunciation":"dayr MIS-shtant","example":"Interne Missstände."},{"word":"auflösbar","translation":"resolvable","pronunciation":"OWF-lös-bahr","example":"Spannung auflösbar."}]}',
'{"title":"Rechenschaftspflichtig machen — to hold accountable (transitive accountability)","pattern":"jemanden rechenschaftspflichtig machen = to hold someone accountable (rechenschaftspflichtig = accountable — adjective; machen + adjective = to make/render X; jemanden = accusative — the object held to account)","explanation":"Rechenschaftspflichtig machen = to hold accountable (transitive: jemanden rechenschaftspflichtig machen). Rechenschaft (account/accountability) + pflichtig (obligated) = obligated to give account. Alternative: zur Rechenschaft ziehen (to call to account — stronger — implies process/consequence), verantwortlich machen (to hold responsible — more informal), zur Verantwortung ziehen (to call to responsibility). The machen + adjective construction is versatile: transparent machen (to make transparent), sichtbar machen (to make visible), haftbar machen (to make liable).","examples":[{"sentence":"Wahlen sollen Politiker rechenschaftspflichtig machen.","translation":"Elections are supposed to hold politicians accountable."},{"sentence":"Die Presse macht die Regierung rechenschaftspflichtig.","translation":"The press holds the government accountable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zurückhalten'' means?","options":["to withhold","to hold back","to retain","to suppress"],"correctAnswer":"to withhold"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Freedom of information is a structural prerequisite for democratic control: only when citizens have access to information about government action can they hold their governments to account and make informed political decisions. Authorities that withhold information shift the balance of power in favour of the administration.","options":["Informationsfreiheit ist eine strukturelle Voraussetzung demokratischer Kontrolle: Nur wenn Bürgerinnen und Bürger Zugang zu Informationen über Regierungshandeln haben, können sie ihre Regierungen rechenschaftspflichtig machen und fundierte politische Entscheidungen treffen. Behörden, die Informationen zurückhalten, verschieben das Machtgefüge zugunsten der Verwaltung.","Ohne Informationsfreiheit gibt es keine demokratische Kontrolle.","Bürger können Regierungen nur kontrollieren, wenn sie Zugang zu Informationen haben.","Informationsrückhalt verschiebt Macht hin zur Verwaltung."],"correctAnswer":"Informationsfreiheit ist eine strukturelle Voraussetzung demokratischer Kontrolle: Nur wenn Bürgerinnen und Bürger Zugang zu Informationen über Regierungshandeln haben, können sie ihre Regierungen rechenschaftspflichtig machen und fundierte politische Entscheidungen treffen. Behörden, die Informationen zurückhalten, verschieben das Machtgefüge zugunsten der Verwaltung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Presse macht die Regierung ___.","options":["rechenschaftspflichtig","verantwortlich","haftbar","transparent"],"correctAnswer":"rechenschaftspflichtig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Elections are supposed to hold politicians accountable","wordBankItems":["Wahlen","sollen","Politiker","rechenschaftspflichtig","machen","."],"correctAnswer":"Wahlen sollen Politiker rechenschaftspflichtig machen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Machtgefüge'' means?","options":["balance of power","power structure","power relationship","power system"],"correctAnswer":"balance of power"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss cybersecurity and the state at B2","Use Cybersicherheit und Staat vocabulary","Talk about Germany''s cybersecurity infrastructure, hybrid threats, and state responsibility"],"explanation":{"intro":"Cybersecurity and the state vocabulary covers hybrid warfare, Germany''s cyber defences, and debates about digital sovereignty at B2.","culturalNote":"Cybersicherheit und Staat: Germany: BSI (Bundesamt für Sicherheit in der Informationstechnik — Federal Office for Information Security — Bonn — key cyber authority). Hybrid warfare: cyber attacks as part of state-sponsored aggression (Russia — Bundestag hack 2015 — attributed to APT28). Kritische Infrastruktur (critical infrastructure — KRITIS — energy, water, transport — protected under BSI-Gesetz). Cyberangriffe auf Kommunen (2021 Landkreis Anhalt-Bitterfeld — ransomware — state of emergency — first German case). Zero-Day vulnerabilities. Digitale Souveränität (digital sovereignty — EU Cloud Act, European cloud providers GAIA-X). Key debate: Staatstrojaner (state spyware — intelligence services using vulnerabilities — FinFisher, Pegasus analogue)."},"examples":[{"german":"Cybersicherheit ist zur Staatsaufgabe geworden, weil kritische Infrastruktur im digitalen Raum angreifbar ist: Energieversorgung, Wasserwerke, Krankenhäuser und Verwaltungssysteme sind im Störungsfall keine isolierten Schadensereignisse, sondern Angriffe auf die Daseinsvorsorge ganzer Bevölkerungen.","english":"Cybersecurity has become a state responsibility because critical infrastructure is attackable in digital space: energy supply, waterworks, hospitals, and administrative systems in the event of disruption are not isolated damage events, but attacks on the public welfare of entire populations."},{"german":"Hybride Bedrohungen stellen klassische Kriegsdefinitionen auf den Prüfstand: Cyberangriffe, Desinformationskampagnen und wirtschaftliche Druckmittel können staatliche Institutionen destabilisieren, ohne die Schwelle bewaffneter Konflikte zu überschreiten — und erfordern deshalb neue rechtliche Kategorien, die zwischen Friedens- und Kriegszustand operieren.","english":"Hybrid threats put classical war definitions to the test: cyber attacks, disinformation campaigns, and economic leverage instruments can destabilise state institutions without crossing the threshold of armed conflict — and therefore require new legal categories operating between peace and war."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s BSI, hybrid warfare, and critical infrastructure protection at B2."}}',
'{"items":[{"word":"angreifbar","translation":"attackable/vulnerable","pronunciation":"AN-gry-fahr","example":"Infrastruktur angreifbar."},{"word":"die Daseinsvorsorge","translation":"public welfare/essential services","pronunciation":"dee DAH-zyns-for-zor-geh","example":"Daseinsvorsorge schützen."},{"word":"die Bedrohung","translation":"threat","pronunciation":"dee beh-DROH-oong","example":"Hybride Bedrohung."},{"word":"destabilisieren","translation":"to destabilise","pronunciation":"deh-stah-bi-li-ZEE-ren","example":"Institutionen destabilisieren."},{"word":"überschreiten","translation":"to cross/exceed","pronunciation":"ü-ber-SHRY-ten","example":"Schwelle überschreiten."},{"word":"auf den Prüfstand stellen","translation":"to put to the test","pronunciation":"owf dayn PRÜF-shtant shtel-en","example":"Definitionen auf den Prüfstand stellen."}]}',
'{"title":"Auf den Prüfstand stellen — to put to the test (subjecting a concept to rigorous examination)","pattern":"etwas stellt X auf den Prüfstand = something puts X to the test (auf den Prüfstand stellen = to put to the test — Prüfstand = testing stand/bench — figuratively: rigorous examination of a claim or concept)","explanation":"Auf den Prüfstand stellen = to put to the test (lit. to place on the testing bench). Hybride Bedrohungen stellen klassische Kriegsdefinitionen auf den Prüfstand = Hybrid threats put classical war definitions to the test. The phrase implies that X (a concept, theory, policy) faces scrutiny that may reveal its inadequacy. Compare: in Frage stellen (to question — challenges whether something is valid), auf die Probe stellen (to put to the test — more about a person''s qualities), infrage stellen (to question — challenges validity), auf Herz und Nieren prüfen (to examine thoroughly — more exhaustive), überprüfen (to review/check — more neutral).","examples":[{"sentence":"Die Krise hat unser gesamtes Planungsmodell auf den Prüfstand gestellt.","translation":"The crisis has put our entire planning model to the test."},{"sentence":"Neue Fakten stellen die alte Theorie auf den Prüfstand.","translation":"New facts put the old theory to the test."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Daseinsvorsorge'' means?","options":["public welfare/essential services","public services","social welfare","basic provision"],"correctAnswer":"public welfare/essential services"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hybrid threats put classical war definitions to the test: cyber attacks, disinformation campaigns, and economic leverage instruments can destabilise state institutions without crossing the threshold of armed conflict — and therefore require new legal categories operating between peace and war.","options":["Hybride Bedrohungen stellen klassische Kriegsdefinitionen auf den Prüfstand: Cyberangriffe, Desinformationskampagnen und wirtschaftliche Druckmittel können staatliche Institutionen destabilisieren, ohne die Schwelle bewaffneter Konflikte zu überschreiten — und erfordern deshalb neue rechtliche Kategorien, die zwischen Friedens- und Kriegszustand operieren.","Cyberangriffe sind eine neue Form des Krieges, die bestehende Rechtsbegriffe herausfordert.","Hybride Kriegsführung liegt zwischen Frieden und bewaffnetem Konflikt.","Neue Bedrohungsformen erfordern neue rechtliche Kategorien."],"correctAnswer":"Hybride Bedrohungen stellen klassische Kriegsdefinitionen auf den Prüfstand: Cyberangriffe, Desinformationskampagnen und wirtschaftliche Druckmittel können staatliche Institutionen destabilisieren, ohne die Schwelle bewaffneter Konflikte zu überschreiten — und erfordern deshalb neue rechtliche Kategorien, die zwischen Friedens- und Kriegszustand operieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise hat unser Planungsmodell auf den Prüfstand ___.","options":["gestellt","gebracht","gezogen","gesetzt"],"correctAnswer":"gestellt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: New facts put the old theory to the test","wordBankItems":["Neue","Fakten","stellen","die","alte","Theorie","auf","den","Prüfstand","."],"correctAnswer":"Neue Fakten stellen die alte Theorie auf den Prüfstand ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überschreiten'' means?","options":["to cross/exceed","to surpass","to transgress","to go beyond"],"correctAnswer":"to cross/exceed"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital education at B2","Use Digitale Bildung vocabulary","Talk about Germany''s digital education gap, EdTech, and media literacy"],"explanation":{"intro":"Digital education vocabulary covers Germany''s digital education gap, EdTech, and media literacy at B2.","culturalNote":"Digitale Bildung: Germany: notoriously slow to digitise schools — only accelerated by COVID-19. Key: DigitalPakt Schule (2019 — €5bn for school digitisation — slow rollout — Länderkompetenz problem). Medienkompetenz (media literacy — Bildungsauftrag). Key debate: Smartphones in schools (Handyverbot — ban). Educational platforms: Moodle, Antolin, itslearning. Key institution: KMK (Kultusministerkonferenz — Standing Conference of the Ministers of Education — 16 Länder — coordination problem). PISA 2022: Germany bottom third on digital skills. Key figures: Beat Döbeli Honegger (''Mehr als 0 und 1''). Key concept: Computational Thinking. Digitale Spaltung (digital divide) in education — rural-urban, rich-poor."},"examples":[{"german":"Die digitale Bildungslücke ist kein Problem fehlender Geräte, sondern fehlender pädagogischer Konzepte: Tablets in Klassenzimmern verändern nicht automatisch die Lernqualität — entscheidend ist, ob Lehrkräfte Digitaltechnologie didaktisch sinnvoll integrieren können und ob Schülerinnen und Schüler als aktive Produzenten statt als passive Konsumenten digitaler Inhalte ausgebildet werden.","english":"The digital education gap is not a problem of missing devices, but of missing pedagogical concepts: tablets in classrooms do not automatically improve learning quality — what is decisive is whether teachers can integrate digital technology in a didactically meaningful way and whether students are educated as active producers rather than passive consumers of digital content."},{"german":"Medienkompetenz umfasst mehr als technische Bedienung: Die Fähigkeit, Quellen zu bewerten, Desinformation zu erkennen, Datenschutz zu verstehen und eigene digitale Spuren zu reflektieren, gehört zu den Grundvoraussetzungen politischer Partizipation in digitalen Gesellschaften — und bleibt in deutschen Lehrplänen weitgehend unterrepräsentiert.","english":"Media literacy encompasses more than technical operation: the ability to evaluate sources, recognise disinformation, understand data protection, and reflect on one''s own digital footprint belongs to the basic prerequisites for political participation in digital societies — and remains largely underrepresented in German curricula."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s digital education gap, media literacy, and DigitalPakt at B2."}}',
'{"items":[{"word":"pädagogisch","translation":"pedagogical","pronunciation":"pä-dah-GO-gish","example":"Pädagogisches Konzept."},{"word":"didaktisch","translation":"didactic","pronunciation":"di-DAK-tish","example":"Didaktisch sinnvoll."},{"word":"integrieren","translation":"to integrate","pronunciation":"in-teh-GREE-ren","example":"Technologie integrieren."},{"word":"der Produzent","translation":"producer","pronunciation":"dayr pro-doo-TSENT","example":"Aktiver Produzent."},{"word":"umfassen","translation":"to encompass","pronunciation":"oom-FAS-en","example":"Medienkompetenz umfasst."},{"word":"unterrepräsentiert","translation":"underrepresented","pronunciation":"oon-ter-reh-prä-zen-TEERT","example":"Unterrepräsentiert im Lehrplan."}]}',
'{"title":"X umfasst mehr als Y — X encompasses more than Y (scope expansion)","pattern":"X umfasst mehr als Y = X encompasses more than Y (umfassen = to encompass/comprise — transitive; mehr als = more than — scope expansion: the concept X is broader than what Y alone captures)","explanation":"X umfasst mehr als Y = X encompasses more than Y. Medienkompetenz umfasst mehr als technische Bedienung = Media literacy encompasses more than technical operation. The pattern expands the scope of a concept beyond a common but inadequate understanding: the usual definition (Y) is correct but insufficient — X is broader. Compare: geht über X hinaus (goes beyond X — more directional), X beschränkt sich nicht auf Y (X does not limit itself to Y — more from Y''s perspective), mehr als nur X (more than just X — simpler), X bedeutet auch Y (X also means Y — additive rather than expansive).","examples":[{"sentence":"Demokratie umfasst mehr als freie Wahlen.","translation":"Democracy encompasses more than free elections."},{"sentence":"Bildung umfasst mehr als Wissensvermittlung.","translation":"Education encompasses more than the transmission of knowledge."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Pädagogisch'' means?","options":["pedagogical","educational","didactic","instructional"],"correctAnswer":"pedagogical"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Media literacy encompasses more than technical operation: the ability to evaluate sources, recognise disinformation, understand data protection, and reflect on one''s own digital footprint belongs to the basic prerequisites for political participation in digital societies — and remains largely underrepresented in German curricula.","options":["Medienkompetenz umfasst mehr als technische Bedienung: Die Fähigkeit, Quellen zu bewerten, Desinformation zu erkennen, Datenschutz zu verstehen und eigene digitale Spuren zu reflektieren, gehört zu den Grundvoraussetzungen politischer Partizipation in digitalen Gesellschaften — und bleibt in deutschen Lehrplänen weitgehend unterrepräsentiert.","Medienkompetenz bedeutet mehr als das Bedienen digitaler Geräte.","Quellenkritik, Datenschutz und digitale Selbstreflexion fehlen in deutschen Lehrplänen.","Digitale Bildung muss über technische Fähigkeiten hinausgehen."],"correctAnswer":"Medienkompetenz umfasst mehr als technische Bedienung: Die Fähigkeit, Quellen zu bewerten, Desinformation zu erkennen, Datenschutz zu verstehen und eigene digitale Spuren zu reflektieren, gehört zu den Grundvoraussetzungen politischer Partizipation in digitalen Gesellschaften — und bleibt in deutschen Lehrplänen weitgehend unterrepräsentiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Demokratie umfasst mehr als freie ___.","options":["Wahlen","Abstimmungen","Entscheidungen","Rechte"],"correctAnswer":"Wahlen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Education encompasses more than the transmission of knowledge","wordBankItems":["Bildung","umfasst","mehr","als","Wissensvermittlung","."],"correctAnswer":"Bildung umfasst mehr als Wissensvermittlung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterrepräsentiert'' means?","options":["underrepresented","inadequately covered","missing","absent"],"correctAnswer":"underrepresented"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss technology and democracy at B2","Use Technologie und Demokratie vocabulary","Talk about digital democracy, e-participation, and tech governance in Germany"],"explanation":{"intro":"Technology and democracy vocabulary covers digital democracy tools, tech governance, and the relationship between digital infrastructure and democratic institutions at B2.","culturalNote":"Technologie und Demokratie: Key: can digital tools strengthen democracy or threaten it? Positive: E-Petitionen (e-petitions — Bundestag — since 2005 — millions of signatures), Onlinebeteiligung (online participation), Liquid Democracy (direct+representative hybrid — Piratenpartei). Negative: Disinformation, foreign interference (Russland-Hacks), social media polarisation. Key German case: Bundestagswahl 2017 — Russian influence attempt (FSB/GRU allegedly). Platform power over speech. EU responses: DSA (Digital Services Act 2022 — platform accountability), DMA (Digital Markets Act — competition). Key debate: Digital sovereignty (Digitale Souveränität) vs. reliance on US Big Tech for democratic infrastructure. GAIA-X (European cloud initiative — Germany/France 2019). Key concept: Internet Governance (multi-stakeholder model vs. state control — UN IGF)."},"examples":[{"german":"Die Frage, ob digitale Technologien Demokratien stärken oder untergraben, lässt sich nicht pauschal beantworten: E-Partizipationsinstrumente können Bürgerbeteiligung senken, während algorithmische Desinformation sie destabilisieren kann — die demokratische Qualität digitaler Infrastruktur hängt von ihrem Designprinzip und ihrer Regulierungsarchitektur ab.","english":"The question of whether digital technologies strengthen or undermine democracies cannot be answered in a blanket manner: e-participation instruments can lower the threshold for citizen participation, while algorithmic disinformation can destabilise it — the democratic quality of digital infrastructure depends on its design principle and regulatory architecture."},{"german":"Digitale Souveränität ist kein technischer, sondern ein politischer Begriff: Wer die Infrastruktur für demokratische Kommunikation, Wahlen und öffentliche Verwaltung kontrolliert, kontrolliert damit auch die Bedingungen der demokratischen Praxis selbst — ein Umstand, der europäische Abhängigkeit von US-amerikanischen Plattformen als strategisches Risiko erscheinen lässt.","english":"Digital sovereignty is not a technical but a political concept: whoever controls the infrastructure for democratic communication, elections, and public administration also thereby controls the conditions of democratic practice itself — a circumstance that makes European dependence on US-American platforms appear as a strategic risk."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital sovereignty, EU tech regulation, and technology-democracy tensions at B2."}}',
'{"items":[{"word":"pauschal","translation":"blanket/sweeping","pronunciation":"POWSH-al","example":"Pauschal beantworten."},{"word":"die Beteiligung","translation":"participation","pronunciation":"dee beh-TY-li-goong","example":"Bürgerbeteiligung."},{"word":"die Abhängigkeit","translation":"dependence","pronunciation":"dee AB-heng-ikh-kyt","example":"Abhängigkeit von Plattformen."},{"word":"damit","translation":"thereby","pronunciation":"dah-MIT","example":"Damit kontrollieren."},{"word":"erscheinen als","translation":"to appear as","pronunciation":"er-SHY-nen als","example":"Als Risiko erscheinen."},{"word":"die Souveränität","translation":"sovereignty","pronunciation":"dee zo-veh-rä-ni-TÄT","example":"Digitale Souveränität."}]}',
'{"title":"X lässt sich nicht pauschal beantworten — X cannot be answered in a blanket manner","pattern":"etwas lässt sich nicht pauschal beantworten = something cannot be answered in a blanket/sweeping manner (sich lassen + infinitive = can be/is able to be — passive equivalent; pauschal = blanket/sweeping — marks refusing oversimplification)","explanation":"Lässt sich nicht...beantworten = cannot be answered (sich lassen + infinitive = passive modal: ''can be done''). Pauschal = in a blanket manner, sweepingly, oversimplifyingly (from Pauschale = lump sum, bulk). Die Frage lässt sich nicht pauschal beantworten = The question cannot be answered in a blanket manner. The construction refuses easy generalisation and opens space for nuanced contextual answers. Compare: nicht verallgemeinerbar (not generalisable — adjective), je nach Kontext (depending on context), differenziert betrachten (to consider in a differentiated way — positive framing of nuance), eine pauschale Antwort wäre irreführend (a blanket answer would be misleading).","examples":[{"sentence":"Die Frage nach der besten Methode lässt sich nicht pauschal beantworten.","translation":"The question of the best method cannot be answered in a blanket manner."},{"sentence":"Kulturelle Unterschiede lassen sich nicht pauschal bewerten.","translation":"Cultural differences cannot be assessed in a blanket manner."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Pauschal'' means?","options":["blanket/sweeping","general","overall","universal"],"correctAnswer":"blanket/sweeping"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital sovereignty is not a technical but a political concept: whoever controls the infrastructure for democratic communication, elections, and public administration also thereby controls the conditions of democratic practice itself — a circumstance that makes European dependence on US-American platforms appear as a strategic risk.","options":["Digitale Souveränität ist kein technischer, sondern ein politischer Begriff: Wer die Infrastruktur für demokratische Kommunikation, Wahlen und öffentliche Verwaltung kontrolliert, kontrolliert damit auch die Bedingungen der demokratischen Praxis selbst — ein Umstand, der europäische Abhängigkeit von US-amerikanischen Plattformen als strategisches Risiko erscheinen lässt.","Kontrolle über digitale Infrastruktur ist politische Macht.","Europas Abhängigkeit von US-amerikanischen Plattformen ist ein demokratisches Risiko.","Wer digitale Infrastruktur besitzt, hat Macht über demokratische Prozesse."],"correctAnswer":"Digitale Souveränität ist kein technischer, sondern ein politischer Begriff: Wer die Infrastruktur für demokratische Kommunikation, Wahlen und öffentliche Verwaltung kontrolliert, kontrolliert damit auch die Bedingungen der demokratischen Praxis selbst — ein Umstand, der europäische Abhängigkeit von US-amerikanischen Plattformen als strategisches Risiko erscheinen lässt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Frage nach der besten Methode lässt sich nicht pauschal ___.","options":["beantworten","klären","lösen","bestimmen"],"correctAnswer":"beantworten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Cultural differences cannot be assessed in a blanket manner","wordBankItems":["Kulturelle","Unterschiede","lassen","sich","nicht","pauschal","bewerten","."],"correctAnswer":"Kulturelle Unterschiede lassen sich nicht pauschal bewerten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Abhängigkeit'' means?","options":["dependence","dependency","reliance","subordination"],"correctAnswer":"dependence"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

